/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.html5;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import page2020.util.EmptyUtil;import page2020.view.Content;import page2020.view.Element;public class H5iframe extends Element<H5iframe, Content<?>> {	public static final class Attr {		public static final String allowFullScreen = "allowfullscreen";		public static final String allowPaymentRequest = "allowpaymentrequest";		public static final String height = "height";		public static final String name = "name";		public static final String referrerPolicy = "referrerpolicy";		public static final String sandBox = "sandbox";		public static final String src = "src";		public static final String width = "width";	}	public static final class ValueOfSandBox {		public static final String allowForms = "allow-forms";		public static final String allowPointerLock = "allow-pointer-lock";		public static final String allowPopups = "allow-popups";		public static final String allowSameOrigin = "allow-same-origin";		public static final String allowScripts = "allow-scripts";		public static final String allowTopNavigation = "allow-top-navigation";	}	private static Logger log = LoggerFactory.getLogger(H5iframe.class);	public H5iframe() {		super("iframe");	}	public H5iframe allowFullScreen(boolean allowFullScreen) {		super.getAttrMap().put(Attr.allowFullScreen, allowFullScreen);		return this;	}	public H5iframe allowPaymentRequest(boolean allowPaymentRequest) {		super.getAttrMap().put(Attr.allowPaymentRequest, allowPaymentRequest);		return this;	}	public H5iframe height(String pixels) {		if (EmptyUtil.not(pixels)) {			super.getAttrMap().put(Attr.height, pixels.trim());		} else {			log.error("height: argument(pixels) is empty !");		}		return this;	}	public H5iframe h5Name(String h5name) {		if (EmptyUtil.not(h5name)) {			super.getAttrMap().put(Attr.name, h5name.trim());		} else {			log.error("h5Name: argument(name) is empty !");		}		return this;	}	public H5iframe referrerPolicy(String referrerPolicy) {		if (EmptyUtil.not(referrerPolicy)) {			super.getAttrMap().put(Attr.referrerPolicy, referrerPolicy.trim());		} else {			log.error("referrerPolicy: argument(referrerPolicy) is empty !");		}		return this;	}	public H5iframe sandBox(String sandBox) {		if (EmptyUtil.not(sandBox)) {			super.getAttrMap().put(Attr.sandBox, sandBox.trim());		} else {			log.error("sandBox: argument(sandBox) is empty !");		}		return this;	}	public H5iframe src(String path) {		if (EmptyUtil.not(path)) {			super.getAttrMap().put(Attr.src, path.trim());		} else {			log.error("src: argument(path) is empty !");		}		return this;	}	public H5iframe width(String pixels) {		if (EmptyUtil.not(pixels)) {			super.getAttrMap().put(Attr.width, pixels.trim());		} else {			log.error("width: argument(pixels) is empty !");		}		return this;	}	@Override	protected boolean isAttr(String attrName) {		switch (super.attrName(attrName)) {		case Attr.allowFullScreen:		case Attr.allowPaymentRequest:		case Attr.height:		case Attr.name:		case Attr.referrerPolicy:		case Attr.sandBox:		case Attr.src:		case Attr.width:			return true;		default:			return super.isAttr(attrName);		}	}}